from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    """Apply the first matching rewrite rule to each URL."""

    def host_matches(host, match_value):
        host = (host or "").lower()
        match_value = match_value.lower()

        if match_value.startswith("*."):
            suffix = match_value[2:]
            # Must be a strict subdomain, not the domain itself.
            return host.endswith("." + suffix) and host != suffix

        return host == match_value

    def replace_host(parsed, new_host):
        """Replace only the hostname, preserving credentials and port."""
        username = parsed.username
        password = parsed.password
        port = parsed.port

        userinfo = ""
        if username is not None:
            userinfo = username
            if password is not None:
                userinfo += ":" + password
            userinfo += "@"

        # Bracket IPv6 hostnames when reconstructing the netloc.
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        netloc = userinfo + new_host
        if port is not None:
            netloc += f":{port}"

        return parsed._replace(netloc=netloc)

    result = []

    for url in urls:
        parsed = urlsplit(url)
        rewritten = url
        applied = False

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            matches = False

            if match_type == "path_prefix":
                matches = parsed.path.startswith(match_value)

            elif match_type == "host":
                matches = host_matches(parsed.hostname, match_value)

            elif match_type == "query_param":
                query_names = {
                    name for name, _ in parse_qsl(
                        parsed.query,
                        keep_blank_values=True
                    )
                }
                matches = match_value in query_names

            if not matches:
                continue

            applied = True

            if action == "block":
                rewritten = None

            elif action == "strip_prefix":
                path = parsed.path
                prefix = rule["action_value"]

                if path.startswith(prefix):
                    path = path[len(prefix):]

                if not path:
                    path = "/"

                rewritten = urlunsplit(parsed._replace(path=path))

            elif action == "redirect_host":
                rewritten = urlunsplit(
                    replace_host(parsed, rule["action_value"])
                )

            elif action == "add_query_param":
                query = parsed.query
                addition = rule["action_value"]
                new_query = f"{query}&{addition}" if query else addition
                rewritten = urlunsplit(parsed._replace(query=new_query))

            break  # Only the first applicable rule is used.

        result.append(rewritten)

    return result
